-- =====================================================================
-- MERCADOWEB (Capi-Barato) — Esquema PostgreSQL para Supabase
-- Equivalente 1:1 del esquema MySQL de sql/mercadoweb.sql.
-- =====================================================================
--
-- Equivalencias aplicadas (ninguna tabla se elimina ni se simplifica):
--
--   INT UNSIGNED AUTO_INCREMENT  ->  INTEGER GENERATED BY DEFAULT AS IDENTITY
--        "BY DEFAULT" (y no "ALWAYS") para que los datos semilla puedan fijar ids explícitos.
--        PostgreSQL nombra la secuencia "<tabla>_<columna>_seq", que es justo lo que espera
--        ultimoId() en api/includes/db.php para reemplazar a lastInsertId().
--   UNSIGNED                     ->  CHECK (columna >= 0), que es la restricción real que aportaba
--   ENUM(...)                    ->  tipo enumerado propio (CREATE TYPE), misma restricción
--   TINYINT UNSIGNED             ->  SMALLINT + CHECK
--   DECIMAL(10,2)                ->  NUMERIC(10,2)
--   DATETIME                     ->  TIMESTAMP (SIN zona horaria), igual que DATETIME en MySQL.
--        La zona la fija la conexión (SET TIME ZONE, ver db.php), así CURRENT_TIMESTAMP guarda la
--        hora local de la tienda y el formato que recibe el frontend es idéntico al de MySQL.
--   ON UPDATE CURRENT_TIMESTAMP  ->  disparador (PostgreSQL no tiene esa cláusula)
--   INDEX dentro de CREATE TABLE ->  CREATE INDEX aparte
--
-- unaccent: lo necesita la búsqueda del catálogo. En MySQL, ignorar mayúsculas y acentos lo daba
-- la collation utf8mb4_unicode_ci; en PostgreSQL hay que pedirlo explícitamente (ver sqlContiene()).
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS unaccent;

-- ---------------------------------------------------------------------
-- Tipos enumerados (equivalen a los ENUM de MySQL)
-- ---------------------------------------------------------------------
CREATE TYPE estado_activo    AS ENUM ('activo', 'inactivo');
CREATE TYPE rol_usuario      AS ENUM ('admin', 'cliente');
CREATE TYPE estado_pedido    AS ENUM ('pendiente', 'pagado', 'enviado', 'completado', 'cancelado');

-- ---------------------------------------------------------------------
-- Disparador reutilizable para fecha_actualizacion
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION tocar_fecha_actualizacion()
RETURNS TRIGGER AS $$
BEGIN
    NEW.fecha_actualizacion := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- categorias
-- ---------------------------------------------------------------------
CREATE TABLE categorias (
    id_categoria    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre          VARCHAR(50) NOT NULL,
    slug            VARCHAR(50) NOT NULL,
    fecha_creacion  TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_categorias_slug UNIQUE (slug)
);

-- ---------------------------------------------------------------------
-- productos
-- ---------------------------------------------------------------------
CREATE TABLE productos (
    id_producto           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_categoria          INTEGER        NOT NULL,
    nombre                VARCHAR(150)   NOT NULL,
    stock                 INTEGER        NOT NULL DEFAULT 0,
    precio_original       NUMERIC(10,2)  NOT NULL,
    descuento_porcentaje  SMALLINT       NULL,
    proveedor             VARCHAR(100)   NULL,
    envio_gratis          BOOLEAN        NOT NULL DEFAULT FALSE,
    costo_envio           NUMERIC(10,2)  NULL,
    estado                estado_activo  NOT NULL DEFAULT 'activo',
    fecha_creacion        TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion   TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_productos_categoria FOREIGN KEY (id_categoria)
        REFERENCES categorias(id_categoria) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT chk_productos_stock CHECK (stock >= 0),
    CONSTRAINT chk_productos_precio CHECK (precio_original >= 0),
    CONSTRAINT chk_productos_descuento
        CHECK (descuento_porcentaje IS NULL OR descuento_porcentaje BETWEEN 1 AND 99),
    CONSTRAINT chk_productos_costo_envio
        CHECK (envio_gratis = TRUE OR costo_envio IS NOT NULL)
);
CREATE INDEX idx_productos_categoria_estado ON productos (id_categoria, estado);
CREATE TRIGGER trg_productos_actualizacion BEFORE UPDATE ON productos
    FOR EACH ROW EXECUTE FUNCTION tocar_fecha_actualizacion();

-- ---------------------------------------------------------------------
-- producto_imagenes
-- ---------------------------------------------------------------------
CREATE TABLE producto_imagenes (
    id_imagen     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_producto   INTEGER      NOT NULL,
    url_imagen    VARCHAR(255) NOT NULL,
    orden         SMALLINT     NOT NULL DEFAULT 1,
    CONSTRAINT fk_imagenes_producto FOREIGN KEY (id_producto)
        REFERENCES productos(id_producto) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_imagenes_orden CHECK (orden >= 0)
);
CREATE INDEX idx_imagenes_producto ON producto_imagenes (id_producto);

-- ---------------------------------------------------------------------
-- producto_caracteristicas
-- ---------------------------------------------------------------------
CREATE TABLE producto_caracteristicas (
    id_caracteristica  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_producto        INTEGER      NOT NULL,
    descripcion        VARCHAR(255) NOT NULL,
    orden              SMALLINT     NOT NULL DEFAULT 1,
    CONSTRAINT fk_caracteristicas_producto FOREIGN KEY (id_producto)
        REFERENCES productos(id_producto) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_caracteristicas_orden CHECK (orden >= 0)
);
CREATE INDEX idx_caracteristicas_producto ON producto_caracteristicas (id_producto);

-- ---------------------------------------------------------------------
-- usuarios
-- ---------------------------------------------------------------------
CREATE TABLE usuarios (
    id_usuario      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre          VARCHAR(100)  NOT NULL,
    email           VARCHAR(150)  NOT NULL,
    password_hash   VARCHAR(255)  NOT NULL,
    rol             rol_usuario   NOT NULL DEFAULT 'cliente',
    estado          estado_activo NOT NULL DEFAULT 'activo',
    fecha_registro  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_usuarios_email UNIQUE (email)
);

-- ---------------------------------------------------------------------
-- carrito_items  (carrito de servidor — solo usuarios logueados)
-- ---------------------------------------------------------------------
CREATE TABLE carrito_items (
    id_item              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario           INTEGER   NOT NULL,
    id_producto          INTEGER   NOT NULL,
    cantidad             INTEGER   NOT NULL DEFAULT 1,
    fecha_agregado       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_carrito_usuario FOREIGN KEY (id_usuario)
        REFERENCES usuarios(id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_carrito_producto FOREIGN KEY (id_producto)
        REFERENCES productos(id_producto) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_carrito_cantidad CHECK (cantidad >= 1),
    CONSTRAINT uq_carrito_usuario_producto UNIQUE (id_usuario, id_producto)
);
CREATE TRIGGER trg_carrito_actualizacion BEFORE UPDATE ON carrito_items
    FOR EACH ROW EXECUTE FUNCTION tocar_fecha_actualizacion();

-- ---------------------------------------------------------------------
-- pedidos
-- ---------------------------------------------------------------------
CREATE TABLE pedidos (
    id_pedido        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario       INTEGER        NOT NULL,
    fecha_pedido     TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    estado           estado_pedido  NOT NULL DEFAULT 'pendiente',
    subtotal         NUMERIC(10,2)  NOT NULL,
    costo_envio      NUMERIC(10,2)  NOT NULL DEFAULT 0,
    total            NUMERIC(10,2)  NOT NULL,
    direccion_envio  VARCHAR(255)   NULL,
    CONSTRAINT fk_pedidos_usuario FOREIGN KEY (id_usuario)
        REFERENCES usuarios(id_usuario) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX idx_pedidos_usuario ON pedidos (id_usuario);

-- ---------------------------------------------------------------------
-- detalle_pedido  (snapshot inmutable del precio al momento de la compra)
-- ---------------------------------------------------------------------
CREATE TABLE detalle_pedido (
    id_detalle       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pedido        INTEGER        NOT NULL,
    id_producto      INTEGER        NOT NULL,
    cantidad         INTEGER        NOT NULL,
    precio_unitario  NUMERIC(10,2)  NOT NULL,
    subtotal         NUMERIC(10,2)  NOT NULL,
    CONSTRAINT fk_detalle_pedido FOREIGN KEY (id_pedido)
        REFERENCES pedidos(id_pedido) ON DELETE CASCADE ON UPDATE CASCADE,
    -- RESTRICT es intencional: nunca debe poder borrarse un producto con historial de ventas.
    CONSTRAINT fk_detalle_producto FOREIGN KEY (id_producto)
        REFERENCES productos(id_producto) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT chk_detalle_cantidad CHECK (cantidad >= 0)
);
CREATE INDEX idx_detalle_pedido ON detalle_pedido (id_pedido);

-- ---------------------------------------------------------------------
-- sesiones  (tabla NUEVA — ver api/includes/sesion_bd.php)
--
-- En serverless el disco no se comparte entre instancias ni sobrevive, así que las sesiones en
-- archivos de PHP se pierden al azar. Como el token CSRF vive en la sesión, eso rompería toda
-- operación de escritura. Esta tabla las hace compartidas y duraderas.
-- ---------------------------------------------------------------------
CREATE TABLE sesiones (
    id                VARCHAR(128) PRIMARY KEY,
    datos             TEXT         NOT NULL,
    fecha_expiracion  TIMESTAMP    NOT NULL
);
CREATE INDEX idx_sesiones_expiracion ON sesiones (fecha_expiracion);

-- ---------------------------------------------------------------------
-- intentos_login  (tabla NUEVA — ver api/includes/limite_intentos.php)
--
-- Contador anti fuerza bruta. Antes vivía en archivos del directorio temporal: en serverless cada
-- instancia tiene el suyo y se borra, con lo que el límite no servía de nada.
-- "clave" es un SHA-256 de IP + correo: no se guarda ninguno de los dos en claro.
-- ---------------------------------------------------------------------
CREATE TABLE intentos_login (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clave    CHAR(64)  NOT NULL,
    momento  TIMESTAMP NOT NULL
);
CREATE INDEX idx_intentos_clave_momento ON intentos_login (clave, momento);
